let lang=0,index=0,toastID;const $=s=>document.querySelector(s),tr=(r,k)=>lang?k:r,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={teamSelected:null,simMode:'work',ethic:0,case:0,gaps:new Set(),prompt:{},frac:{},word:new Set(),cat:'noun',water:[null,null,null,null],history:[null,null,null],checks:new Set(),fixed:false,rev:false,walk:0,physicsTab:0,u:6,r:10,match:['','','',''],editor:{},presenter:'',feedback:{}};
const timeDefs={1:300,2:420,3:300,4:720},timers=Object.fromEntries(Object.entries(timeDefs).map(([k,v])=>[k,{left:v,running:false,end:0}]));
const activity=n=>{const i=originalIndex(n);return i===5?1:[18,19].includes(i)?2:i===28?3:[39,40].includes(i)?4:0};
const sources=[['Personalize ChatGPT','https://learn.chatgpt.com/docs/personalize','Предпочтения и инструкции|Қалаулар мен нұсқаулар'],['Models','https://learn.chatgpt.com/docs/models','Модели и глубина рассуждения|Модельдер және пайымдау тереңдігі'],['Space','https://learn.chatgpt.com/docs/space','Рабочие пространства и страницы|Жұмыс кеңістіктері мен беттер'],['Sites','https://learn.chatgpt.com/docs/sites','Создание и публикация сайтов|Сайт жасау және жариялау'],['Use ChatGPT','https://learn.chatgpt.com/docs/use-chatgpt','Способы работы|Жұмыс тәсілдері'],['Collaborate in Space','https://learn.chatgpt.com/docs/space/collaboration','Просмотр, комментарии, редактирование|Қарау, пікір, өңдеу'],['Pricing and usage','https://learn.chatgpt.com/docs/pricing','Проверка текущих лимитов|Ағымдағы лимиттерді тексеру']];
const btn=(text,action,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
const link=(url,label,cls='')=>`<a href="${url}" target="_blank" rel="noopener noreferrer" class="${cls}">${label} ↗</a>`;
function cards(s){return `<div class="grid" style="--cols:${Math.min(s.cards.length,4)}">${s.cards.map((c,i)=>{let [a,...b]=c[lang].split(':');return `<div class="card"><span class="num">${String(i+1).padStart(2,'0')}</span><p><strong>${esc(a)}</strong>${esc(b.join(':'))}</p></div>`}).join('')}</div>`}
function partners(){return `<div class="partnerbar"><img src="/*FREEDOM*/" alt="Freedom Holding Corp." style="width:116px;height:32px;background:white;border-radius:3px;padding:4px"><img src="/*OPENAI*/" alt="OpenAI" style="width:103px;height:29px;background:white;border-radius:3px;padding:5px"><span>Astana Hub</span><span>BilimLand</span></div>`}
function toast(t){$('#toast').textContent=t;clearTimeout(toastID);toastID=setTimeout(()=>$('#toast').textContent='',3500)}
function modal(title,html,drawer=false){const d=$('#dialog');d.classList.remove('ethics-dialog','privacy-dialog','sim-projects-dialog');d.classList.toggle('drawer',drawer);$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;if(!d.open)d.showModal();}
function promptText(kind){if(kind==='personal')return tr('Я педагог. Отвечай на русском языке, кратко и понятно. Сохраняй точные учебные цели. Отделяй материал ученика от ответов учителя. Не выдумывай факты, нормативные требования и ссылки. Обозначай неопределённость. Предлагай способ проверки результата.','Мен педагогпін. Қазақ тілінде қысқа әрі түсінікті жауап бер. Нақты оқу мақсаттарын сақта. Оқушы материалын мұғалім жауаптарынан бөл. Фактілерді, нормативтік талаптарды және сілтемелерді ойдан шығарма. Белгісіздікті көрсет. Нәтижені тексеру тәсілін ұсын.');
if(kind==='html')return tr('Создай одно небольшое HTML-задание для [класс] по предмету [предмет]. Тема: [тема]. Учебная цель: [точная цель учителя]. Используй [проверенный источник и ключ]. Ученик должен [наблюдаемое действие]. Язык: [русский / казахский].\nДобавь понятную инструкцию, проверку ответа, объяснение ошибки, повторную попытку и перезапуск. Обработай пустой и неверный ответ. Не начисляй баллы повторно за тот же вопрос.\nОбъедини HTML, CSS и JavaScript в одном index.html. Все ресурсы встроены, без внешних библиотек и сетевых запросов. Поддержи клавиатуру, экран 320 px и чёткий контраст. Не собирай персональные данные.\nСохрани проверенное содержание. Не выдумывай недостающие факты. Предоставь готовый файл для скачивания. Проверь правильный, неверный и пустой ответ, сброс и офлайн-работу. Приложи короткую инструкцию.','[Сынып] сыныбына [пән] пәнінен бір шағын HTML тапсырма жаса. Тақырып: [тақырып]. Оқу мақсаты: [мұғалімнің дәл мақсаты]. [Тексерілген дереккөз бен кілтті] қолдан. Оқушы [бақыланатын әрекет] орындайды. Тілі: [қазақша / орысша].\nТүсінікті нұсқау, жауапты тексеру, қатені түсіндіру, қайталау және қайта бастау болсын. Бос және қате жауапты өңде. Бір сұраққа қайта ұпай берме.\nHTML, CSS және JavaScript бір index.html файлында болсын. Барлық ресурс кіріктірілген, сыртқы кітапханасыз және желілік сұраныссыз. Пернетақта, 320 px экран және анық контраст қолдауын қос. Жеке дерек жинама.\nТексерілген мазмұнды сақта. Жетіспейтін фактіні ойдан қоспа. Жүктеуге дайын файл ұсын. Дұрыс, қате, бос жауапты, қайта бастауды және офлайн жұмысты тексер. Қысқа нұсқаулық қос.');
return builderPrompt();}
function showPrompt(kind){modal(tr('Готовый промпт','Дайын промпт'),`<pre id="copyText">${esc(promptText(kind))}</pre>${btn(tr('Копировать','Көшіру'),'copy:modal','primary')}`)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast(tr('Скопировано','Көшірілді'))}catch{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();let ok=false;try{ok=document.execCommand('copy')}catch{}t.remove();if(ok)toast(tr('Скопировано','Көшірілді'));else modal(tr('Скопируйте текст вручную','Мәтінді қолмен көшіріңіз'),`<textarea rows="12">${esc(text)}</textarea>`);}}
const personalHTML=()=>`<div class="promptline">${tr('Язык: русский. Стиль: кратко.<br>Цели: сохранять. Факты: проверять.','Тіл: қазақша. Стиль: қысқа.<br>Мақсат: сақтау. Факт: тексеру.')}</div><div class="actions">${btn(tr('Полная инструкция','Толық нұсқаулық'),'prompt:personal','primary')}${btn(tr('Копировать','Көшіру'),'copy:personal')}</div>`;
function fraction(id,cover=false){const state=S.frac[id]||{first:null,last:null};return `<div class="exercise"><span class="pill">${tr(cover?'Подготовленный пример':'Одинаковые знаменатели',cover?'Дайын үлгі':'Бөлімдері бірдей')}</span><div class="formula">1/4 + 2/4 = ?</div><div class="options">${['3/8','3/4','2/4'].map((x,i)=>btn(x,`frac:${id}:${i}`,state.last===i?'active':'')).join('')}</div><div class="feedback ${state.last===null?'':state.last===1?'good':'bad'}" role="status">${state.last===null?tr('Выберите ответ.','Жауапты таңдаңыз.'):state.last===1?tr('Верно: (1 + 2) / 4 = 3/4.','Дұрыс: (1 + 2) / 4 = 3/4.'):tr('Знаменатель сохраняем, числители складываем. Попробуйте ещё.','Бөлімін сақтап, алымдарын қосамыз. Қайталап көріңіз.')}</div><div class="row">${btn(tr('Сначала','Қайта бастау'),`fracreset:${id}`,'small-btn')}${!cover?`<span class="fine">${tr('Первый ответ','Бірінші жауап')}: ${state.first===null?'—':state.first===1?'1 / 1':'0 / 1'}</span>`:''}</div></div>`}
const ethicsDetails=[['Цель и доступность','Мақсат пен қолжетімділік','ИИ помогает учебной цели. Предусмотрите вариант для ученика без устройства и понятный язык.','ЖИ оқу мақсатына көмектеседі. Құрылғысы жоқ оқушыға балама мен түсінікті тіл ұсыныңыз.'],['Минимум данных','Деректерді азайту','«Ученик А затрудняется складывать дроби». Уберите имя, школу, контакты и косвенные признаки. Даже заменённое имя не гарантирует анонимность.','«Оқушы А бөлшектерді қосуда қиналады». Есім, мектеп, байланыс пен жанама белгілерді алып тастаңыз. Есімді ауыстыру иесіздендіруге кепіл емес.'],['Авторство и достоверность','Авторлық пен сенімділік','«Материал подготовлен с помощью ИИ, проверен и адаптирован педагогом». Реальные результаты исследования нельзя заменять выдуманными. Ссылку нужно открыть и сопоставить с утверждением.','«Материал ЖИ көмегімен дайындалып, педагог тексеріп, бейімдеді». Нақты зерттеу нәтижесін ойдан алынғанмен алмастыруға болмайды. Сілтемені ашып, тұжырыммен салыстыру қажет.']];
const cases=[['Список учеников с оценками','Оқушылар тізімі мен бағалары','Загрузить имена и оценки в общий чат?','Есімдер мен бағаларды ортақ чатқа жүктеу керек пе?',1,'Нельзя в таком виде. Уберите прямые и косвенные идентификаторы, сократите данные и используйте одобренную среду.','Осы күйінде болмайды. Тікелей және жанама белгілерді алып тастап, деректерді азайтыңыз, мақұлданған ортаны қолданыңыз.'],['Непроверенная ссылка','Тексерілмеген сілтеме','Использовать найденный ИИ факт в уроке?','ЖИ тапқан фактіні сабақта қолдануға бола ма?',2,'Нужны условия: откройте первоисточник, проверьте дату и соответствие утверждению. Если подтверждения нет, исключите факт.','Шарт керек: түпнұсқаны ашып, күнін және тұжырымға сәйкестігін тексеріңіз. Расталмаса, фактіні алып тастаңыз.'],['Результаты исследования','Зерттеу нәтижелері','Придумать измерения вместо проведённого опыта?','Тәжірибе орнына өлшеу нәтижесін ойдан жазуға бола ма?',1,'Нельзя выдавать вымышленные результаты за реальные. Допустим отдельно обозначенный учебный набор для тренировки анализа.','Ойдан алынған нәтижені нақты деп көрсетуге болмайды. Талдауды үйренуге арнайы белгіленген оқу деректерін қолдануға болады.']];
function caseHTML(){let c=cases[S.case];return `<div class="tabs">${cases.map((a,i)=>btn('0'+(i+1)+' '+a[lang],`case:${i}`,S.case===i?'active':'')).join('')}</div><div class="exercise"><h2>${c[lang+2]}</h2><div class="options">${[tr('Можно','Болады'),tr('Нельзя','Болмайды'),tr('Нужны условия','Шарт керек')].map((x,i)=>btn(x,`caseanswer:${i}`)).join('')}</div></div>`}
function routeHTML(){const items=[['Введение и проект BilimAI','Кіріспе және BilimAI жобасы'],['Этика и безопасное применение ИИ','ЖИ этикасы және қауіпсіз қолдану'],['ChatGPT Edu: интерфейс, Workspace и Codex','ChatGPT Edu: интерфейс, Workspace және Codex'],['Промпт-инжиниринг','Промпт құрастыру'],['Плагины и навыки BilimAI','BilimAI плагиндері мен дағдылары'],['Создание и проверка HTML-материалов','HTML материалдарын жасау және тексеру'],['ChatGPT Edu Champions','ChatGPT Edu Champions'],['Итоги, ресурсы и вопросы','Қорытынды, ресурстар және сұрақтар']];return '<ol class="seminar-plan">'+items.map(item=>'<li>'+item[lang]+'</li>').join('')+'</ol>';}
const promptLabels=[['Предмет','Пән'],['Класс','Сынып'],['Тема','Тақырып'],['Цель','Мақсат'],['Источник','Дереккөз'],['Формат','Пішім'],['Время','Уақыт'],['Критерий','Өлшем']];
const promptDefaults=[['Математика','Математика'],['5','5'],['Сложение дробей','Бөлшектерді қосу'],['Складывать дроби с одинаковыми знаменателями','Бөлімдері бірдей бөлшектерді қосу'],['Пример 1/4 + 2/4 = 3/4','1/4 + 2/4 = 3/4 мысалы'],['3 задания и ключ отдельно','3 тапсырма, кілт бөлек'],['7 минут','7 минут'],['Верный ответ и объяснение','Дұрыс жауап және түсіндірме']];
const pv=i=>S.prompt[lang+'-'+i]??promptDefaults[i][lang];
function builderPrompt(){return promptLabels.map((a,i)=>`${a[lang]}: ${pv(i)}.`).join('\n')+'\n'+tr('Сохрани цель. Не выдумывай источники. Проверь ключи и время.','Мақсатты сақта. Дереккөздерді ойдан қоспа. Кілттер мен уақытты тексер.');}
function builderHTML(){return `<div class="select-grid" style="grid-template-columns:repeat(4,1fr)">${promptLabels.map((a,i)=>`<label class="field">${a[lang]}<input data-prompt="${i}" value="${esc(pv(i))}"></label>`).join('')}</div><div class="actions">${btn(tr('Собрать промпт','Промпт құрастыру'),'prompt:builder','primary')}${btn(tr('Разбор изменений','Өзгерістерді талдау'),'builderreview')}</div>`}
const waterLabels=[['Испарение','Булану'],['Конденсация','Конденсация'],['Осадки','Жауын-шашын'],['Накопление воды','Судың жиналуы']];
const histLabels=[['Независимость','Тәуелсіздік'],['Государственные символы','Мемлекеттік рәміздер'],['Введение тенге','Теңгенің енгізілуі']];
function orderHTML(kind){const a=kind==='water'?waterLabels:histLabels,st=S[kind];return `<div class="order">${a.map((_,i)=>`<div><span>0${i+1}</span><label class="field">${kind==='water'?tr('Этап','Кезең'):['16.12.1991','04.06.1992','15.11.1993'][i]}<select data-order="${kind}" data-slot="${i}"><option value="">${tr('Выберите','Таңдаңыз')}</option>${[...a.keys()].reverse().map(j=>`<option value="${j}" ${st[i]===j?'selected':''}>${a[j][lang]}</option>`).join('')}</select></label></div>`).join('')}</div><div class="actions">${btn(tr('Проверить','Тексеру'),`ordercheck:${kind}`,'primary')}${btn(tr('Сначала','Қайта бастау'),`orderreset:${kind}`)}${kind==='history'?link('https://www.gov.kz/memleket/entities/mfa-kuala-lumpur/press/news/details/244973?lang=ru',tr('Официальный источник','Ресми дереккөз'),'fine'):''}</div><div class="feedback" id="orderFeedback" role="status"></div>`}
function physicsHTML(){if(S.physicsTab===1)return tabs()+`<div class="exercise"><h2>${tr('Язык: найти действие','Тіл: әрекетті табу')}</h2><p class="big-text">${tr('Ученик читает книгу.','Оқушы кітап оқиды.')}</p>${btn(tr('Читает','Оқиды'),'language-mini','primary')}</div>`;if(S.physicsTab===2)return tabs()+`<div class="flow"><div><b>01</b>${tr('Задать число 3','3 санын беру')}</div><div><b>02</b>${tr('Умножить на 2','2-ге көбейту')}</div><div><b>03</b>${tr('Прибавить 1','1 қосу')}</div></div>${btn(tr('Показать результат','Нәтижені көрсету'),'algorithm')}`;return tabs()+`<div class="split"><div class="controls"><label>${tr('Напряжение U','Кернеу U')}: <b id="uval">${S.u}</b> ${tr('В','В')}<input aria-label="U" id="voltage" type="range" min="1" max="12" value="${S.u}"></label><label>${tr('Сопротивление R','Кедергі R')}: <b id="rval">${S.r}</b> ${tr('Ом','Ом')}<input aria-label="R" id="resistance" type="range" min="1" max="20" value="${S.r}"></label>${btn(tr('Начальные значения','Бастапқы мәндер'),'physicsreset')}</div><div class="reading"><h2>I = U / R</h2><div class="metric" id="ival">${(S.u/S.r).toFixed(2).replace('.',',')} <span style="font-size:35px">A</span></div><p>${tr('Идеальный резистор','Идеал резистор')}</p></div></div>`}
function tabs(){return `<div class="tabs">${[tr('Физика','Физика'),tr('Языки','Тілдер'),tr('Информатика','Информатика')].map((x,i)=>btn(x,`physicstab:${i}`,S.physicsTab===i?'active':'')).join('')}</div>`}
function languageHTML(){return `<div class="tabs">${btn('Зат есім','cat:noun',S.cat==='noun'?'active':'')}${btn('Етістік','cat:verb',S.cat==='verb'?'active':'')}</div><div class="exercise"><p class="hint">${tr('Выберите все слова выбранной части речи.','Таңдалған сөз табына жататын барлық сөзді таңдаңыз.')}</p><div class="chipset" style="margin:20px 0">${['Бала','кітап','оқиды'].map((x,i)=>`<button class="word" data-action="word:${i}" aria-pressed="${S.word.has(i)}">${x}</button>`).join('')}</div><div class="actions">${btn(tr('Проверить','Тексеру'),'wordcheck','primary')}${btn(tr('Сначала','Қайта бастау'),'wordreset')}</div><div id="wordFeedback" class="feedback" role="status"></div></div>`}
const helpers=['Ustaz BilimAI Mektep','Tarbie BilimAI Mektep','Tarbieshi BilimAI Balabaksha','Canva'];
