document.addEventListener('input',e=>{let t=e.target;if(t.matches('[data-prompt]'))S.prompt[lang+'-'+t.dataset.prompt]=t.value;if(t.matches('[data-edit]')){S.editor[lang]={...editorValues(),[t.dataset.edit]:t.value}}if(t.id==='defect')S.defect=t.value;if(t.classList.contains('presenter'))S.presenter=t.value;if(t.id==='voltage'||t.id==='resistance'){S.u=+$('#voltage').value;S.r=+$('#resistance').value;$('#uval').textContent=S.u;$('#rval').textContent=S.r;$('#ival').innerHTML=(S.u/S.r).toFixed(2).replace('.',',')+' <span style="font-size:35px">A</span>'}});
document.addEventListener('change',e=>{let t=e.target;if(t.matches('[data-order]'))S[t.dataset.order][+t.dataset.slot]=t.value===''?null:+t.value;if(t.matches('[data-match]'))S.match[+t.dataset.match]=t.value;if(t.matches('[data-check]'))t.checked?S.checks.add(+t.dataset.check):S.checks.delete(+t.dataset.check)});
document.addEventListener('submit',e=>e.preventDefault());
$('#menuBtn').onclick=showMenu;$('#notesBtn').onclick=showNotes;$('#sourcesBtn').onclick=showSources;$('#closeDialog').onclick=()=>$('#dialog').close();$('#prev').onclick=()=>goto(index-1);$('#next').onclick=()=>goto(index+1);$('#ru').onclick=()=>{lang=0;render()};$('#kk').onclick=()=>{lang=1;render()};$('#fullBtn').onclick=async()=>{try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen()}catch{toast(tr('Используйте F11 в браузере.','Браузерде F11 қолданыңыз.'))}};
function showSimPersonalization(step=0){closeSimProfile();const images=['/*SIMPERSONAL1*/','/*SIMPERSONAL2*/'];modal(tr('Персонализация','Жекелендіру')+' · '+(step+1)+' / 2',`<div class="sim-personal-nav">${step===1?btn(tr('← Назад','← Артқа'),'sim-personal:0'): '<span></span>'}${step===0?btn(tr('Далее →','Әрі қарай →'),'sim-personal:1','primary'): '<span></span>'}</div><img id="simPersonalScreen" src="${images[step]}" alt="${step===0?'Персонализация: память и пользовательские инструкции':'Характеристики и дополнительные настройки ChatGPT'}" style="display:block;width:100%;height:auto">`);$('#dialogBody').scrollTop=0;}
function renderTeam(){const selected=methodologists[S.teamSelected];$('#slide').className='slide team-slide';if(selected){$('#slide').innerHTML=`<h1 id="slideTitle" class="sr">${esc(selected.name)}</h1><img class="team-full" src="${selected.image}" alt="${esc(selected.name)} — полная карточка"><button class="team-back" data-action="team-back">← ${tr('К методологам','Әдіскерлерге оралу')}</button>`;return;}$('#slide').innerHTML=`<h1 id="slideTitle" class="sr">${tr('Методологи Bilim Group','Bilim Group әдіскерлері')}</h1><div class="team-logo" aria-label="Bilim Group"><img src="${methodologists[0].image}" alt="Bilim Group"></div>${methodologists.map((m,i)=>{const [x,y,w,iw]=m.crop;return `<button class="team-person" data-action="team-open:${i}" style="left:${m.pos[0]}px;top:${m.pos[1]}px" aria-label="${tr('Открыть карточку: ','Карточканы ашу: ')}${esc(m.name)}"><span class="team-photo"><img src="${m.image}" alt="" style="width:${iw/w*100}%;left:${-x/w*100}%;top:${-y/w*100}%"></span><span class="team-name">${esc(m.name)}</span></button>`}).join('')}`;}
function closeSimModel(){$('#simModelMenu')?.remove();$('[data-action="sim:model"]')?.setAttribute('aria-expanded','false');}
function toggleSimModel(){if($('#simModelMenu')){closeSimModel();return;}closeSimProfile();const menu=document.createElement('div');menu.id='simModelMenu';menu.className='sim-model-menu';menu.setAttribute('role','region');menu.setAttribute('aria-label',tr('Список моделей','Модельдер тізімі'));menu.innerHTML='<img src="/*SIMMODELMENU*/" alt="Выбрать модель: по умолчанию, GPT-6 Astra, GPT-5.6 Sol, GPT-5.6 Terra, GPT-5.6 Luna, GPT-5.5"><button class="sim-model-toggle" data-action="sim:model" aria-label="Закрыть список моделей"></button>';$('.simulation-screen').append(menu);$('[data-action="sim:model"]')?.setAttribute('aria-expanded','true');}
function closeSimProfile(){ $('#simProfileMenu')?.remove();$('[data-action="sim:profile"]')?.setAttribute('aria-expanded','false');}
document.addEventListener('click',e=>{if($('#simMoreMenu')&&!e.target.closest('#simMoreMenu,[data-action="sim:more"]'))closeSimMore();if($('#simModelMenu')&&!e.target.closest('#simModelMenu,[data-action="sim:model"]'))closeSimModel();if($('#simProfileMenu')&&!e.target.closest('#simProfileMenu,[data-action="sim:profile"]'))closeSimProfile();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#simMoreMenu')){closeSimMore();$('[data-action="sim:more"]')?.focus();e.preventDefault();return;}if(e.key==='Escape'&&$('#simModelMenu')){closeSimModel();$('[data-action="sim:model"]')?.focus();e.preventDefault();return;}if(e.key==='Escape'&&slides[index].kind==='team'&&S.teamSelected!==null){const selected=S.teamSelected;S.teamSelected=null;render();$('[data-action="team-open:'+selected+'"]')?.focus();e.preventDefault();return;}if(e.key==='Escape'&&$('#simProfileMenu')){closeSimProfile();$('[data-action="sim:profile"]')?.focus();e.preventDefault();return;}if(e.defaultPrevented||e.ctrlKey||e.altKey||e.metaKey||$('#dialog').open||e.target.closest('input,select,textarea,[contenteditable]')||(e.key===' '&&e.target.closest('button,a')))return;if(['ArrowRight','ArrowLeft',' '].includes(e.key)){e.preventDefault();goto(index+(e.key==='ArrowLeft'?-1:1))}});
window.addEventListener('resize',fit);window.addEventListener('hashchange',()=>{let n=Number(location.hash.replace('#slide-',''));if(Number.isInteger(n)&&n>=1&&n<=slides.length&&index!==n-1){index=n-1;render()}});setInterval(timerUpdate,250);let initial=Number(location.hash.replace('#slide-',''));if(initial>=1&&initial<=slides.length)index=initial-1;render();


