function renderAIParadigms(){
const items=[
 ['ЗАМЕЩЕНИЕ','АЛМАСТЫРУ','Replacement','ИИ выполняет отдельные задачи вместо учителя: проверяет работы, составляет планы и материалы. Это экономит время, но повышает риск ослабления самостоятельности мышления и профессиональной субъектности педагога.','ЖИ мұғалімнің орнына жекелеген міндеттерді орындайды: жұмыстарды тексереді, жоспарлар мен материалдар жасайды. Уақытты үнемдейді, бірақ ойлау дербестігі мен педагог субъектілігінің әлсіреу қаупін арттырады.'],
 ['ДОПОЛНЕНИЕ','ТОЛЫҚТЫРУ','Complementarity','Учитель и ИИ работают в тандеме. ИИ предоставляет данные, скорость и масштаб; учитель сохраняет эмпатию, понимание контекста и моральное суждение. Окончательное решение остаётся за педагогом.','Мұғалім мен ЖИ тандемде жұмыс істейді. ЖИ дерек, жылдамдық және ауқым береді; мұғалім эмпатияны, контексті және моральдық пайымды сақтайды. Соңғы шешім педагогте қалады.'],
 ['УСИЛЕНИЕ','КҮШЕЙТУ','Augmentation','При глубокой интеграции учитель и ИИ развивают друг друга. Связка «учитель + ИИ» даёт результат выше возможностей каждого по отдельности: компетенции педагога расширяются, но не автоматизируются.','Терең кіріктіру кезінде мұғалім мен ЖИ бірін-бірі дамытады. «Мұғалім + ЖИ» байланысы олардың әрқайсысының жеке мүмкіндігінен жоғары нәтиже береді: педагогтің құзыреті кеңейеді, бірақ автоматтандырылмайды.']
];
$('#slide').className='slide ai-paradigms';$('#slide').innerHTML=`<h1 id="slideTitle">${esc(slides[index].title[lang])}</h1><div class="paradigm-logo" role="img" aria-label="Bilim Group"></div><p class="paradigm-intro">${tr('Роль учителя меняется в зависимости от уровня использования технологии','Мұғалімнің рөлі технологияны қолдану деңгейіне қарай өзгереді')}</p><div class="paradigm-track" aria-hidden="true"></div><div class="paradigm-grid">${items.map((item,i)=>'<section class="paradigm-col"><div class="paradigm-number">'+(i+1)+'</div><div class="paradigm-copy"><h2>'+item[lang]+'</h2><p class="paradigm-english">'+item[2]+'</p><p class="paradigm-body">'+item[3+lang]+'</p></div></section>').join('')}</div><div class="paradigm-source">${tr('Источники: OECD Digital Education Outlook 2026, глава 7; Cukurova, 2024, British Journal of Educational Technology','Дереккөздер: OECD Digital Education Outlook 2026, 7-тарау; Cukurova, 2024, British Journal of Educational Technology')}<span>02</span></div>`;
}

function eduOverviewTopics(){return [
['Workspace — рабочее пространство и выбранный аккаунт.','Workspace — жұмыс кеңістігі және таңдалған тіркелгі.'],
['Чат и режим «Работа» — переключение между экранами.','Чат және «Жұмыс» режимі — экрандар арасында ауысу.'],
['Персонализация — память, инструкции, стиль и тон ответов.','Жекелендіру — жад, нұсқаулар, жауаптардың стилі мен үні.'],
['Space и Page — пространство материалов и работа со страницей.','Space және Page — материалдар кеңістігі және бетпен жұмыс.'],
['Project — организация работы над одной задачей или темой.','Project — бір тапсырма немесе тақырып бойынша жұмысты ұйымдастыру.']
];}

function eduDetails(){return [
{title:['Workspace — рабочая среда','Workspace — жұмыс ортасы'],text:['Это среда ChatGPT, в которой вы сейчас работаете: личная или предоставленная вашей организацией. От выбранного Workspace зависят доступные инструменты и настройки. Аккаунт — это ваша учётная запись, а Workspace — среда, которую вы выбираете внутри неё.','Бұл — сіз қазір жұмыс істеп отырған ChatGPT ортасы: жеке немесе ұйымыңыз ұсынған орта. Қолжетімді құралдар мен баптаулар таңдалған Workspace-ке байланысты. Аккаунт — сіздің тіркелгіңіз, ал Workspace — сол тіркелгі ішінде таңдайтын жұмыс ортасы.'],example:['Учитель входит в свой аккаунт и выбирает рабочее пространство организации для работы в ChatGPT Edu.','Мұғалім өз аккаунтына кіріп, ChatGPT Edu-да жұмыс істеу үшін ұйымның жұмыс кеңістігін таңдайды.'],url:'https://learn.chatgpt.com/docs/space'},
{title:['Чат и режим «Работа» — способы взаимодействия с ChatGPT','Чат және «Жұмыс» режимі — ChatGPT-пен өзара әрекеттесу тәсілдері'],text:['Чат удобен для вопросов, объяснений, обсуждения идей и редактирования текста.','Чат сұрақ қоюға, түсіндіруге, идеяларды талқылауға және мәтінді өңдеуге ыңғайлы.'],extra:['«Работа» подходит для задач, которые требуют нескольких действий и готового результата: документа, презентации, таблицы или отчёта.','«Жұмыс» бірнеше әрекетті және дайын нәтижені қажет ететін тапсырмаларға қолайлы: құжат, презентация, кесте немесе есеп.'],example:['«Объясни, что такое формативное оценивание» — запрос для чата.\n\n«Создай рабочий лист по прикреплённому плану урока и подготовь файл» — задача для режима «Работа».','«Қалыптастырушы бағалаудың не екенін түсіндір» — чатқа арналған сұраныс.\n\n«Тіркелген сабақ жоспары бойынша жұмыс парағын жасап, файл дайында» — «Жұмыс» режиміне арналған тапсырма.'],url:'https://learn.chatgpt.com/docs/web'},
{title:['Персонализация — настройка помощника под себя','Жекелендіру — көмекшіні өзіңізге бейімдеу'],text:['Позволяет указать, как ChatGPT должен с вами общаться: на каком языке, насколько подробно и в каком стиле. При включённой памяти он может учитывать полезную информацию из предыдущих бесед.','ChatGPT сізбен қай тілде, қаншалықты егжей-тегжейлі және қандай стильде сөйлесуі керегін көрсетуге мүмкіндік береді. Жад қосулы болса, ол алдыңғы әңгімелердегі пайдалы ақпаратты ескере алады.'],example:['«Я учитель информатики. Отвечай на русском языке, объясняй простыми словами и приводи примеры для 7 класса».','«Мен информатика мұғалімімін. Орыс тілінде жауап бер, қарапайым сөздермен түсіндір және 7-сыныпқа арналған мысалдар келтір».'],after:['Эти настройки можно изменять.','Бұл баптауларды өзгертуге болады.'],url:'https://learn.chatgpt.com/docs/personalize'},
{title:['Space и Page — место для материалов и отдельная страница','Space және Page — материалдар кеңістігі және жеке бет'],text:['Space можно представить как тематическую папку, объединяющую страницы. Page — отдельная страница, которую можно писать и редактировать вместе с ChatGPT. На ней удобно размещать текст, планы и другие материалы, а также предоставлять коллегам доступ для совместной работы.','Space-ті беттерді біріктіретін тақырыптық қалта ретінде елестетуге болады. Page — ChatGPT-пен бірге жазып, өңдеуге болатын жеке бет. Онда мәтін, жоспарлар және басқа материалдарды орналастырып, бірлесіп жұмыс істеу үшін әріптестерге қолжетімділік беруге болады.'],example:['Space «Методическая работа» содержит страницы «План вебинара», «Инструкции для учителей» и «Полезные материалы».','«Әдістемелік жұмыс» Space кеңістігінде «Вебинар жоспары», «Мұғалімдерге арналған нұсқаулықтар» және «Пайдалы материалдар» беттері бар.'],url:'https://learn.chatgpt.com/docs/space'},
{title:['Project — организация длительной работы над темой','Project — тақырып бойынша ұзақ мерзімді жұмысты ұйымдастыру'],text:['Проект объединяет связанные чаты, файлы, источники и общие инструкции. Он удобен, когда к одной теме нужно возвращаться несколько раз и создавать разные материалы на основе одних документов.','Жоба өзара байланысты чаттарды, файлдарды, дереккөздерді және ортақ нұсқауларды біріктіреді. Бір тақырыпқа бірнеше рет оралып, бір құжаттар негізінде әртүрлі материалдар жасау қажет болғанда ыңғайлы.'],example:['В проект «Физика, 7 класс» можно добавить учебную программу и КТП, а затем вести отдельные чаты для подготовки планов уроков, рабочих листов и презентаций.','«Физика, 7-сынып» жобасына оқу бағдарламасы мен күнтізбелік-тақырыптық жоспарды қосып, кейін сабақ жоспарларын, жұмыс парақтарын және презентацияларды дайындау үшін жеке чаттар жүргізуге болады.']}
];}
function showEduDetail(i){const details=eduDetails();if(!details[i])return;const pictures=['/*EDUWORKSPACE*/','/*EDUCHATWORK*/','/*EDUPERSONAL*/','/*EDUSPACEPAGE*/','/*EDUPROJECT*/'];const ids=i===0?[0,1]:[i];const title=i===0?tr('Workspace, чат и режим «Работа»','Workspace, чат және «Жұмыс» режимі'):details[i].title[lang];const body=ids.map(n=>{const d=details[n];return '<section class="edu-detail">'+(ids.length>1?'<h3 class="edu-detail-heading">'+esc(d.title[lang])+'</h3>':'')+'<img class="edu-topic-image" src="'+pictures[n]+'" alt="'+esc(d.title[lang])+'"><p>'+esc(d.text[lang])+'</p>'+(d.extra?'<p>'+esc(d.extra[lang])+'</p>':'')+'<section class="edu-example"><h3>'+tr(n===2?'Пример инструкции':'Пример',n===2?'Нұсқау мысалы':'Мысал')+'</h3><p>'+esc(d.example[lang])+'</p></section>'+(d.after?'<p>'+esc(d.after[lang])+'</p>':'')+(d.url?'<a class="edu-source" href="'+d.url+'" target="_blank" rel="noopener noreferrer">ChatGPT Learn ↗</a>':'')+'</section>';}).join('');modal(title,body);$('#dialogBody').scrollTop=0;}

function closeSimMore(){$('#simMoreMenu')?.remove();$('[data-action="sim:more"]')?.setAttribute('aria-expanded','false');}
function toggleSimMore(){if($('#simMoreMenu')){closeSimMore();return;}closeSimProfile();closeSimModel();const menu=document.createElement('div');menu.id='simMoreMenu';menu.className='sim-more-menu';menu.setAttribute('role','region');menu.setAttribute('aria-label',tr('Дополнительные инструменты','Қосымша құралдар'));menu.innerHTML='<img src="/*SIMMOREMENU*/" alt="Проекты, Изображения, Карты, GPTs, Агенты, Codex" draggable="false"><button class="sim-projects-button" data-action="sim:projects" aria-label="Проекты" aria-haspopup="dialog" title="Проекты"><img src="/*SIMPROJECTSBUTTON*/" alt="" draggable="false"></button>';$('.simulation-screen').append(menu);const trigger=$('[data-action="sim:more"]');trigger?.setAttribute('aria-expanded','true');trigger?.setAttribute('aria-controls','simMoreMenu');}

function regionNames(){return ['Акмолинская область','Актюбинская область','Алматинская область','Атырауская область','Восточно-Казахстанская область','г. Алматы','г. Астана','г. Шымкент','Жамбылская область','Западно-Казахстанская область','Карагандинская область','Костанайская область','Кызылординская область','Мангистауская область','Область Абай','Область Жетісу','Область Ұлытау','Павлодарская область','Северо-Казахстанская область','Туркестанская область'];}
function renderRegions(){return '<div class="region-list"><img src="/*REGIONLIST*/" alt="Регионы Казахстана">'+regionNames().map((name,i)=>'<button class="region-button" data-action="region:'+i+'" aria-label="'+esc(name)+'" aria-haspopup="dialog" title="'+esc(name)+'" style="top:'+((14+i*32.9)/670*100)+'%"></button>').join('')+'</div>';}
function showRegion(i){const name=regionNames()[i];if(!name)return;modal(name,i===12?'<img class="region-data-image" src="/*IMPORT4*/" alt="Данные Кызылординской области по активации лицензий ChatGPT Edu на 11.09.2026">':'<p>'+tr('Данные по этому региону пока не добавлены.','Бұл өңір бойынша деректер әлі қосылмаған.')+'</p>');if(i===12)$('#dialog').classList.add('sim-projects-dialog');$('#dialogBody').scrollTop=0;}

function fileLimitsContent(){return [{"title":"ChatGPT Edu: лимиты и готовые файлы","subtitle":"Расход ресурса зависит от модели, объёма и сложности работы — не только от числа запросов.","cards":[["Лимиты использования","Доступный ресурс и время его обновления отображаются в аккаунте, если раздел «Использование» доступен.\nНовый чат не восстанавливает лимит."],["Запрос и исходные материалы","Задача, аудитория, язык, источники, объём и формат задают требования к результату.\nНужные материалы дают контекст для работы."],["Готовые файлы","Work, если доступен, позволяет работать над готовыми материалами.\nDOCX — документ · PPTX — презентация\nXLSX — таблица · PDF — печать\nРедактируемый формат удобен для доработки."],["Качество результата","Готовый файл требует проверки содержания, оформления и возможности редактирования.\nТочные замечания к странице, слайду или ячейке помогают доработать материал."]],"exampleTitle":"Пример результата для учителя","example":"На основе исходного документа — памятка для учителей на русском языке: 2 страницы в редактируемом DOCX. Перед использованием материал проходит проверку фактов и оформления.","note":"Точные лимиты и доступные функции зависят от условий аккаунта."},{"title":"ChatGPT Edu: лимиттер және дайын файлдар","subtitle":"Ресурс шығыны сұраулар санына ғана емес, модельге, жұмыс көлемі мен күрделілігіне байланысты.","cards":[["Пайдалану лимиттері","Қолжетімді ресурс пен жаңару уақыты аккаунтта көрсетіледі, егер «Пайдалану» бөлімі қолжетімді болса.\nЖаңа чат лимитті қалпына келтірмейді."],["Сұрау және бастапқы материалдар","Міндет, аудитория, тіл, дереккөздер, көлем мен формат нәтижеге қойылатын талаптарды анықтайды.\nҚажетті материалдар жұмысқа контекст береді."],["Дайын файлдар","Work қолжетімді болса, дайын материалдармен жұмыс істеуге мүмкіндік береді.\nDOCX — құжат · PPTX — презентация\nXLSX — кесте · PDF — басып шығару\nӨңделетін формат жетілдіруге ыңғайлы."],["Нәтиженің сапасы","Дайын файлдың мазмұны, безендірілуі және өңдеу мүмкіндігі тексеруді қажет етеді.\nБетке, слайдқа немесе ұяшыққа қатысты нақты ескертулер материалды жетілдіруге көмектеседі."]],"exampleTitle":"Мұғалімге арналған нәтиже мысалы","example":"Бастапқы құжат негізінде мұғалімдерге арналған орыс тіліндегі жадынама: өңдеуге болатын DOCX форматында 2 бет. Қолданар алдында материалдың фактілері мен безендірілуі тексеріледі.","note":"Нақты лимиттер мен қолжетімді функциялар аккаунт шарттарына байланысты."}];}
function renderFileLimits(){const d=fileLimitsContent()[lang];$('#slide').className='slide file-limits-slide';$('#slide').innerHTML='<h1>'+esc(d.title)+'</h1><p class="file-limits-subtitle">'+esc(d.subtitle)+'</p><div class="file-limits-grid">'+d.cards.map((c,i)=>'<article><h2>'+esc(c[0])+'</h2><p>'+esc(c[1])+'</p></article>').join('')+'</div><div class="file-limits-example"><h2>'+esc(d.exampleTitle)+'</h2><p>'+esc(d.example)+'</p></div><p class="file-limits-note">'+esc(d.note)+'</p>';}

function codexOverviewHTML(){const d=lang?{
 intro:'Codex — бағдарламалар жасауға арналған OpenAI ЖИ-агенті. Ол кодты жазады, түсіндіреді және түзетеді; жоба файлдарымен жұмыс істейді.',
 label:'Мұғалімге арналған мысалдар',items:[['Жасау','Интерактивті тренажёр, тест немесе HTML оқу беті.'],['Жетілдіру','Батырмалар, жауаптарды тексеру және қате жауабына түсіндірме қосу.'],['Тексеру','Кодтағы қателерді іздеу және материалдың жұмысын тексеруге көмектесу.']],
 flow:'Жұмыс қалай жүреді',steps:[['Жоба','Codex ашылып, жұмыс бумасы таңдалады.'],['Міндет','Мұғалім мақсатты, сыныпты, тілді және нәтижені сипаттайды.'],['Орындау','Codex файлдарды жасайды немесе өзгертеді, тексерулер орындайды.'],['Бағалау','Мұғалім нәтижені ашып, мазмұны мен жұмысын тексереді.']],
 example:'«5-сыныпқа бөлшектер бойынша HTML тренажёр жаса: 5 тапсырма, жауаптарды тексеру және түсіндірме».',foot:'Педагогикалық мазмұн мен соңғы шешім мұғалімнің бақылауында.',prompt:'Сұрау мысалы'
}:{intro:'Codex — ИИ-агент OpenAI для создания программ. Он пишет, объясняет и исправляет код, работает с файлами проекта.',
 label:'Примеры для учителя',items:[['Создание','Интерактивный тренажёр, тест или учебная HTML-страница.'],['Доработка','Кнопки, проверка ответов и объяснения ошибок в готовом материале.'],['Проверка','Поиск ошибок в коде и помощь в проверке работы материала.']],
 flow:'Как строится работа',steps:[['Проект','Открывается Codex и выбирается рабочая папка.'],['Задача','Учитель описывает цель, класс, язык и ожидаемый результат.'],['Выполнение','Codex создаёт или изменяет файлы и выполняет проверки.'],['Оценка','Учитель открывает результат, проверяет содержание и работу.']],
 example:'«Создай HTML-тренажёр по дробям для 5 класса: 5 заданий, проверка ответов и объяснения».',foot:'Педагогическое содержание и итоговое решение остаются под контролем учителя.',prompt:'Пример запроса'};
 return '<div class="codex-overview"><div class="codex-top"><section class="codex-intro"><span class="codex-symbol" aria-hidden="true">&lt;/&gt;</span><strong>Codex</strong><p>'+d.intro+'</p></section><section class="codex-capabilities"><h2>'+d.label+'</h2>'+d.items.map((v,i)=>'<div class="codex-capability"><span>'+['＋','↗','✓'][i]+'</span><div><h3>'+v[0]+'</h3><p>'+v[1]+'</p></div></div>').join('')+'</section></div><h2 class="codex-flow-title">'+d.flow+'</h2><div class="codex-flow">'+d.steps.map((v,i)=>'<section><span class="codex-step">0'+(i+1)+'</span><h3>'+v[0]+'</h3><p>'+v[1]+'</p></section>').join('')+'</div><div class="codex-example"><strong>'+d.prompt+'</strong><p>'+d.example+'</p></div><footer class="codex-footer"><span>'+d.foot+'</span><a href="https://learn.chatgpt.com/docs/quickstart" target="_blank" rel="noopener noreferrer">OpenAI Docs ↗</a></footer></div>';}

function promptFoundationHTML(){const d=lang?{
 intro:'Промпт — ЖИ-ға берілетін тапсырма. Нақты сұрау мақсатты, жағдайды және күтілетін нәтижені сипаттайды.',
 formula:'Промпттың 7 элементі',example:'Мысал: қазақ тілі, 5-сынып',labels:['Рөл','Тапсырма','Контекст','Аудитория','Формат','Стиль','Шектеулер'],questions:['ЖИ кімнің рөлінде жауап береді?','Не жасау керек?','Қандай тақырып, мақсат, материал бар?','Кімге арналған?','Нәтиже қандай түрде беріледі?','Тілі мен баяндау мәнері қандай?','Көлемі мен талаптары қандай?'],
 parts:['Сен — балалар жазушысы және қазақ тілі оқулықтарының авторысың.','Лексикалық сөздік қорды байытатын көркем мәтін құрастыр.','Тақырып: тура және ауыспалы мағына, омоним, антоним, синоним.','5-сынып оқушылары, 10–11 жас.','Тақырып, 2–3 абзац және мәтіннен алынған лексикалық мысалдар тізімі.','Қазақ тілінде, жеңіл әрі әсерлі әңгімелеу.','100–120 сөз. Күрделі ғылыми анықтамаларсыз.'],
 foot:'Оқу бағдарламасы мен берілген материалдарға сүйену. Оқу мақсатының кодын ойдан шығармау.',take:'Нақты промпт → бастапқы нұсқа → мұғалімнің тексеруі мен нақтылауы',source:'Дереккөз: берілген презентация, 10, 12–13-слайдтар'
}:{intro:'Промпт — задание для ИИ. Понятный запрос описывает цель, условия работы и ожидаемый результат.',
 formula:'7 элементов промпта',example:'Пример: казахский язык, 5 класс',labels:['Роль','Задача','Контекст','Аудитория','Формат','Стиль','Ограничения'],questions:['В какой роли отвечает ИИ?','Что нужно создать?','Каковы тема, цель и материалы?','Для кого предназначен результат?','В каком виде нужен результат?','Каковы язык и тон изложения?','Каковы объём и требования?'],
 parts:['Ты — детский писатель и автор учебников казахского языка.','Создай художественный текст для обогащения словарного запаса.','Тема: прямое и переносное значение, омонимы, антонимы, синонимы.','Ученики 5 класса, 10–11 лет.','Заголовок, 2–3 абзаца и список лексических примеров из текста.','На казахском языке, лёгкое и выразительное повествование.','100–120 слов. Без сложных научных определений.'],
 foot:'Опора на учебную программу и предоставленные материалы. Код учебной цели не придумывается.',take:'Понятный промпт → первый вариант → проверка и уточнение учителем',source:'Источник: предоставленная презентация, слайды 10, 12–13'};
 return '<div class="prompt-foundation"><p class="prompt-definition">'+d.intro+'</p><div class="prompt-learning-grid"><section><h2>'+d.formula+'</h2><div class="prompt-elements">'+d.labels.map((v,i)=>'<div><span>'+String(i+1).padStart(2,'0')+'</span><section><h3>'+v+'</h3><p>'+d.questions[i]+'</p></section></div>').join('')+'</div></section><section class="prompt-worked"><h2>'+d.example+'</h2>'+d.parts.map((v,i)=>'<p><strong>'+d.labels[i]+'.</strong> '+v+'</p>').join('')+'</section></div><div class="prompt-principle">'+d.foot+'</div><div class="prompt-learning-bottom"><strong>'+d.take+'</strong></div></div>';}

window.addEventListener('message',e=>{const frame=document.querySelector('.plugin-import-slide iframe');if(!frame||e.source!==frame.contentWindow)return;if(e.data?.type==='plugin-import-nav')goto(Math.max(0,Math.min(slides.length-1,index+e.data.delta)));if(e.data?.type==='plugin-import-target'){const target=slides.findIndex(s=>s.kind==='plugin-import'&&s.pluginPage===e.data.slide);if(target>=0)goto(target);}});

function promptActivityHTML(){const url='https://padlet.app/qr-code/s0247q0jcha36fgnyitq?source=image';return '<div class="prompt-activity-layout"><section><p class="prompt-activity-label">'+tr('Практика для учителей','Мұғалімдерге арналған тәжірибе')+'</p><h2>'+tr('От общего запроса — к понятной задаче','Жалпы сұраныстан — нақты тапсырмаға')+'</h2><ol><li>'+tr('Отсканируйте QR-код или откройте задание по кнопке.','QR-кодты сканерлеңіз немесе тапсырманы батырма арқылы ашыңыз.')+'</li><li>'+tr('Улучшите промпт: уточните цель, класс, тему, язык и формат результата.','Промптты жақсартыңыз: мақсатты, сыныпты, тақырыпты, тілді және нәтиже пішімін нақтылаңыз.')+'</li><li>'+tr('Разместите свой вариант и обсудите, почему он стал точнее.','Өз нұсқаңызды жариялап, оның неліктен нақтырақ болғанын талқылаңыз.')+'</li></ol><div class="prompt-activity-result"><strong>'+tr('Результат','Нәтиже')+'</strong><p>'+tr('Промпт, по которому понятно, что создать, для кого и каким должен быть готовый материал.','Не жасау керектігі, кімге арналғаны және дайын материалдың қандай болуы керектігі түсінікті промпт.')+'</p></div></section><aside><img src="assets/prompt-activity-qr.png" alt="QR: Padlet"><a class="primary" href="'+url+'" target="_blank" rel="noopener">'+tr('Открыть задание ↗','Тапсырманы ашу ↗')+'</a><p>'+tr('Наведите камеру телефона на QR-код','Телефон камерасын QR-кодқа бағыттаңыз')+'</p></aside></div>';}
